19	
20	    @PostMapping
21	    public ApiResponse<Object> submit(@RequestBody TaskCreateRequest req, HttpServletRequest httpReq) {
22	        Long userId = (Long) httpReq.getAttribute("userId");
23	        try {
24	            Task task = taskService.submit(
25	                    req.getInputFile(),
26	                    req.getTemplateId(),
27	                    req.getWatermarkContent(),
28	                    req.getWatermarkFontSize(),
29	                    req.getWatermarkPosition(),
30	                    userId
31	            );
32	            return ApiResponse.success("任务已提交", task);
33	        } catch (IllegalArgumentException e) {
34	            return ApiResponse.error(400, e.getMessage());
35	        }
36	    }
37	
